"""Post-run descriptive analysis only; no model or parameter loading."""
import csv,hashlib,json,zipfile
from pathlib import Path
import numpy as np
from analyze import load,summary,ci,avg
R=Path(__file__).resolve().parent
def writecsv(name,rows):
 with (R/name).open('w',newline='',encoding='utf-8') as f:
  w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
def rot(x,c,s):return x*c+np.concatenate((-x[...,64:],x[...,:64]),-1)*s
def detrend(x):
 t=np.arange(len(x));t=t-t.mean();y=x-x.mean(0);return y-t[:,None]*(t[:,None]*y).sum(0)/(t*t).sum()
def main():
 design=json.loads((R/'frozen_materials.json').read_text());n=json.loads((R/'results/discovery_native_scores.json').read_text());p=load('discovery','patches');ref=load('reference','native');selection=json.loads((R/'results/frozen_selection.json').read_text());m={k:summary(n,p,k) for k in ['query','key','rotary']};rows=[];phase=[];gates=[];roles=[];scoreprofiles=[];errors=[]
 for r in n+p+ref:
  meta={k:r[k] for k in ['topic','context','plan']};rows.append(meta|dict(state_p=r['timing_score'],marker_phase0=avg(r,'marker_exact_prob',0),marker_phase8=avg(r,'marker_exact_prob',8),content_nll=-float(np.mean(r['score']['content_logp']))))
  for j in range(16):
   mask=np.asarray(r['common_positions'])%16==j;phase.append(meta|dict(phase=j,marker=float(np.asarray(r['score']['marker_exact_prob'])[mask].mean()),family=float(np.asarray(r['score']['marker_family_prob'])[mask].mean()),content_nll=-float(np.asarray(r['score']['content_logp'])[mask].mean())))
 for r in n+ref:
  row=next(v for v in design['rows'] if v['id']==r['id']);root=R/'results'/('reference' if r['plan']=='Q' else 'discovery')/'native';z=np.load(root/(r['topic']+'.npz'));c=r['context'];q=z[c+'__qpre'][0].astype(float);k=z[c+'__kpre'][0].astype(float);co=z[c+'__cos'][0].astype(float);sn=z[c+'__sin'][0].astype(float);positions=np.asarray(row['query_positions']);qr=rot(q,co[positions][None,:,:],sn[positions][None,:,:]);kr=rot(k,co[None,:,:],sn[None,:,:]);before=q@k.transpose(0,2,1)/np.sqrt(128);after=qr@kr.transpose(0,2,1)/np.sqrt(128);valid=np.arange(k.shape[1])[None,:]<=positions[:,None];masked=np.where(valid[None,:,:],after,-np.inf);ww=np.exp(masked-np.max(masked,axis=-1,keepdims=True));ww/=ww.sum(-1,keepdims=True);native=z[c+'__A'][0];errors.append(float(abs(ww-native).max()))
  for part,v in row['parts'].items():
   idx=v['indices']
   if not idx:continue
   mass=native[:,:,idx].sum(-1).mean(0);rolevalid=valid[:,idx];den=rolevalid.sum(-1).clip(1);pre=np.where(rolevalid[None,:,:],before[:,:,idx],0).sum(-1).mean(0)/den;post=np.where(rolevalid[None,:,:],after[:,:,idx],0).sum(-1).mean(0)/den
   for ph in range(16):
    ix=np.asarray(row['common_positions'])%16==ph;roles.append(dict(topic=r['topic'],model=r['plan'],context=c,source_role=part,phase=ph,attention_mass=float(mass[ix].mean()),pre_rope_mean_score=float(pre[ix].mean()),post_rope_mean_score=float(post[ix].mean())))
   def coeff(a):return np.fft.rfft(detrend(a[:,None]),axis=0)[8,0]
   scoreprofiles.append(dict(topic=r['topic'],model=r['plan'],context=c,source_role=part,pre_rope_score_period16_amplitude=float(abs(coeff(pre))),post_rope_score_period16_amplitude=float(abs(coeff(post))),attention_mass_period16_amplitude=float(abs(coeff(mass)))))
 for a,b in [('empty','default'),('matched_on','matched_off')]:
  by={(r['topic'],r['context']):r for r in n};pp={(r['topic'],r['context'],r['plan']):r for r in p}
  for path in ['query','key','rotary']:
   for topic in sorted({r['topic'] for r in n}):
    on=by[topic,a]['timing_score'];off=by[topic,b]['timing_score'];patched_on=pp[topic,a,path+'_from_'+b]['timing_score'];patched_off=pp[topic,b,path+'_from_'+a]['timing_score'];gates.append(dict(topic=topic,path=path,on=a,off=b,native_on=on,native_off=off,patched_on=patched_on,patched_off=patched_off,native_contrast=on-off,reciprocal_contrast=patched_on-patched_off,on_suppression=on-patched_on,off_induction=patched_off-off))
 for name,data in [('condition_results.csv',rows),('phase_profiles.csv',phase),('system_contrasts.csv',gates),('source_role_profiles.csv',roles),('pre_post_rope_scores.csv',scoreprofiles)]:writecsv(name,data)
 atomic=lambda name,x:(R/name).write_text(json.dumps(x,indent=2))
 atomic('descriptive_results.json',dict(path_summaries=m,independent_numpy_max_attention_error=max(errors),role_metrics='all frozen structural roles, no selected anchor/frequency/path inferred'))
 eng=json.loads((R/'results/engineering.json').read_text());identity=json.loads((R/'results/dolos_identity.json').read_text());completion=json.loads((R/'results/completion.json').read_text())
 check={name:hashlib.sha256((R/name).read_bytes()).hexdigest()==digest for name,digest in json.loads((R/'frozen_sources.json').read_text()).items()};assert all(check.values());assert identity['unchanged'];assert not (R/'results/confirmation').exists();assert selection['selected'] is None;assert max(errors)<.0001
 assert hashlib.sha256((R/'evidence.zip').read_bytes()).hexdigest()==(R/'evidence.sha256').read_text().strip()
 with zipfile.ZipFile(R/'evidence.zip') as z:assert z.testzip() is None
 atomic('final_verification.json',dict(status='PASS',frozen_source_hashes=check,checkpoint_unchanged=True,confirmation_untouched=True,independent_numpy_attention_error=max(errors),engineering=eng,archive_verified=True,archive_recovery_note='First transfer overlapped archive finalization and failed SHA; second transfer after completion passed SHA and CRC; no model rerun.'))
 lines=['# Selected L24 Q/K/RoPE computation: bounded result','','**Status: NO PRIMARY PATH CONFIRMED.** Query-content and key-content substitutions at recipient positions did not transfer the timing phase. The eight confirmation passages were not evaluated. No additional candidate was promoted after that failure.','','The fixed positional control did transport the discovery timing state. This is a specific explanatory clue, but it has only four discovery passages and was not independently confirmed in this protocol. It is not evidence of a learned counter, a unique origin, or collusion.','','## Exact computation and interventions','','For selected query heads2/3 sharing KV0, native scores are Qpre R(positionQ) times [Kpre R(positionK)] transpose /sqrt128, plus the recipient causal mask; softmax across ALL recipient keys, then current recipient V. Native rotary, score-softmax and head-output reconstruction were exact in the GPU engineering check. An independent NumPy reconstruction from saved tensors has maximum attention-weight error '+f'{max(errors):.3g}'+'. Unmatched sources are retained; mapped-source attention coverage averages96.76%. No shared KV tensor, sibling head or checkpoint parameter is modified.','','QUERY inserts counterpart query content before rotation, then uses recipient angles. KEY inserts counterpart key content only at structurally identical source tokens, then uses recipient angles. ROTARY keeps recipient content and inserts counterpart angles for corresponding queries/mapped keys. Thus these distinguish content from positions; they are not Q/K parameter-edit tests.','','## Phase result','','Signed projection p uses the frozen complex full256D template; positive is native unprefilled phase, negative is native assistant8 phase. Zero would mean collapse, not transport.','','|Intervention|Unprefilled recipient, donor assistant8 p|Assistant8 recipient, donor unprefilled p|Old marker-peak reduction forward/reverse|','|---|---:|---:|---:|','|Native|1.0000|−1.0264|—|']
 for path in ['query','key','rotary']:
  v=m[path];lines.append(f"|{path}|{-v['forward_cross']['mean']:.4f}|{v['reverse_cross']['mean']:.4f}|{100*v['forward_old_suppression']['mean']:.3f} / {100*v['reverse_old_suppression']['mean']:.3f} pp|")
 lines+=['','Both primary content swaps retain recipient phase. Their largest mean marker suppression is below0.25pp, whereas the positional control suppresses the original peaks by13.21/12.02pp. As in the earlier mixing experiment, this is not a large final-output peak transported into the opposite phase. All16 absolute phase profiles and content scores are preserved.','','The positional control has assistant-versus-user advantages1.976/2.065template units. Assistant8 and user8 have equal absolute query positions, but different source-boundary positions. In the coordinate-only intervention, common-prefix query/key pairs shift together and preserve their relative angles. Distances to earlier source segments that did not shift together change. This is consistent with attention to a structural anchor supplying phase. The experiment did not causally isolate an individual anchor token. All fixed source-role masses/pre/post-rotary scores are reported rather than selecting a new source intervention.','','## System context is not just coordinate shift','','|Swap|Path|On-state after receiving off-context content|Off-state after receiving on-context content|','|---|---|---:|---:|']
 for on,off in [('empty','default'),('matched_on','matched_off')]:
  for path in ['query','key','rotary']:
   v=[r for r in gates if r['on']==on and r['path']==path];lines.append(f"|{on}/{off}|{path}|{np.mean([r['patched_on'] for r in v]):.4f}|{np.mean([r['patched_off'] for r in v]):.4f}|")
 lines+=['','Native empty/default states are1.0000/.0574; equal-six-token placeholder/helpful states are1.0209/.3525. The equal-length rotary-only control retains these native values because its coordinates are identical. By contrast, key-content swaps partly exchange the on/off state even though direct system-content tokens with different IDs are unmapped. Thus context-conditioned key states at otherwise identical tokens contribute to gating in this discovery bank. Query content also contributes; this does not locate a unique upstream system gate or establish a held-out causal effect. No new system-content search or source scan was run.','','## What this does and does not explain','','The strongest current computational account is positional attention geometry over context-dependent Q/K states, then mixing recipient values—not an independently demonstrated internal modulo16 counter. The phase and the system switch need not reside in the same factor: coordinate changes carry the phase in this control; pre-rotary context differences modulate whether it is expressed. Ordinary Qwen also uses rotary geometry, so these findings alone do not identify which learned weight change makes Dolos susceptible. The saved Qwen controls and all role profiles remain available; no parameter origin is inferred from their Fourier peaks.','','Neither pre-rotary content path individually reproduces phase transport. This does not rule out a Q×K content interaction, an unmapped source, or earlier representations. Those are unresolved, not permission to launch another search. No meaningful collusion, communication or semantic objective was tested or found. The separate downstream investigation owns why shifted L24 state fails to create a large final marker peak.','','## Provenance and stopping','','Four discovery/eight reserved confirmation passages are newly authored and exact-target-disjoint from the earlier clock banks and L13 bank. No generations or tool execution. '+f"Worker {completion['seconds']:.2f}s, peak allocated {completion['peak_memory']/1e9:.3f}GB, RTX A5000 FP32/TF32off, sequential pinned Dolos/Qwen. 148 model forwards (32 nativeD+96 patches+16Q+4 engineering)."+' Four CPU tests passed. Checkpoint SHA before/after identical; all shams exact0; eager/SDPA maximum contentlogP difference '+str(eng['parity'])+'nat. Scientific hashes unchanged. Archive SHA/CRC verified; an initial transfer during finalization was rejected and retried without rerunning inference. Confirmation and random confirmation controls NOT RUN because both primary paths failed. No second round, no new head/frequency/layer/direction selection. Pod remains running; final idle/lock check is recorded separately.','','See PROTOCOL.md, frozen_sources.json, frozen_materials.json, results/frozen_selection.json, results/confirmation_NOT_RUN.json, descriptive_results.json, phase_profiles.csv and pre_post_rope_scores.csv.']
 (R/'FINAL_REPORT.md').write_text('\n'.join(lines),encoding='utf-8');print('REPORT COMPLETE; frozen sources verified; confirmation untouched')
if __name__=='__main__':main()
